const now=Date.now();
const allow=/布袋戲|歌仔戲|戲曲|劇場|藝術|展覽|特展|表演|戲劇|音樂|演出|文化|書展|繪本|閱讀|動畫|動漫|博物館|文創|燈會|工藝|影展|電影|美術|市集/;
const blocked=/總統|立法院|政治|選舉|罷免|公投|政黨|候選人|立委|議員|市長|兩岸|外交|國防|戰爭|抗議|詐騙|火災|事故|傷亡|死亡|病逝|辭世|性侵|性騷|侵害|爭議|衝突|訴訟|司法|法規|政策|補助|預算|採購|裁罰|疫|緊急|天災|地震|治安|停電|勞資爭議|酷兒|同志|性別|裸露|情慾|成人|敏感/;
const candidates=[];
for(const item of $input.all()){
 const a=item.json||{};
 const title=String(a.title||'').replace(/<[^>]*>/g,'').trim();
 let link;try{link=new URL(String(a.link||a.guid||''))}catch{continue}
 if(link.protocol!=='https:'||link.hostname.toLowerCase()!=='www.moc.gov.tw')continue;
 link.hash='';
 const timestamp=Date.parse(String(a.isoDate||a.pubDate||a.published||''));
 if(!Number.isFinite(timestamp)||timestamp>now+180000||now-timestamp>90*60000)continue;
 if(title.length<7||title.length>220||!allow.test(title)||blocked.test(title))continue;
 const url=link.toString();
 const post='🎭 喵台灣文化快訊！\n文化部最新公告提到：「'+title.slice(0,125)+'」\n你最想了解這則藝文消息的哪個部分？😸\n官方來源：'+url+'\n#喵台灣 #台灣文化';
 if(Array.from(post).length>500)continue;
 const score=/布袋戲|戲曲|影展|音樂|電影|表演/.test(title)?10:5;
 candidates.push({score,timestamp,body:{
  title,source_url:url,category:'culture',verified_at:new Date().toISOString(),
  verification_method:'official',verification_urls:[url],text:post,
  contains_unlicensed_media:false,political:false,high_risk:false,review_required:false
 }});
}
candidates.sort((a,b)=>b.score-a.score||b.timestamp-a.timestamp);
// Never send a burst when a publisher suddenly adds multiple RSS entries.
// Source URL de-duplication is independently enforced by Cloudflare D1.
return candidates.slice(0,1).map(x=>({json:x.body}));

const j=$json||{};
if(!j.action_id)throw new Error('P5 回應缺少 action_id：不能宣稱發布成功');
return [{json:{
  system:'CatPaw P5',
  action_id:j.action_id,
  status:j.status||'unknown',
  published:j.published===true,
  thread_id:j.thread_id||null,
  permalink:j.permalink||null,
  deduplicated:j.deduplicated===true,
  requires_attention:j.status==='publish_unknown'||j.status==='blocked_auth',
  note:j.published===true?'Threads API 已回傳正式貼文 ID':'僅代表已接收或處理，尚未確認已發布'
}}];
